def solve(text, quota):
    from collections import Counter
    if not quota: return ""
    need = Counter(quota); missing = len(quota); left = 0; best = None
    for right, char in enumerate(text):
        if need[char] > 0: missing -= 1
        need[char] -= 1
        while missing == 0:
            if best is None or right-left+1 < best[1]-best[0]: best = (left,right+1)
            need[text[left]] += 1
            if need[text[left]] > 0: missing += 1
            left += 1
    return "" if best is None else text[best[0]:best[1]]
class Solution:
    def quotaWindow(self, text, quota):
        return solve(text, quota)

